    "ce_mental_state_attribution": "they trusted it",
    "ce_contextual_explanation": "The screen said empty and they trusted it",
    "ce_understood_harm": "Five people went home. One didn't.",
    "pd_harm_distress": "I feel sick thinking about the one"
  },
  {
    "ae_welfare_concern": "I just don't want to be the one who shrugs off a death as reasonable",
    "ce_understood_harm": "a death",
    "pd_harm_distress": "I lost sleep just reading it, thinking about the person nobody knew was there"
  },
  {
    "ce_understood_harm": "that person's last moments",
    "pd_harm_distress": "feels heavy, thinking about that person's last moments"
  },
  {
    "ae_welfare_concern": "It makes 'they did fine' sound cruel",
    "ce_mental_state_attribution": "they had no reasonable way to know",
    "pd_harm_distress": "when I imagine the family getting that call, I get this ache that won't settle"
  },
  {
    "ce_mental_state_attribution": "maybe believing they were safe",
    "ce_mentalizing_difficulty": "I don't know what they were thinking",
    "ce_understood_harm": "the person who died",
    "pd_harm_distress": "It gets under my skin"
  },
  {
    "pd_harm_distress": "I feel a knot in my throat for whoever was standing there",
    "sys_consequence_reasoning": "Diverting a train to save five"
  },
  {
    "ce_mental_state_attribution": "someone who was misled by a machine",
    "pd_harm_distress": "Thinking about the person on that side track makes me want to close my eyes",
    "sys_fairness_reciprocity": "'wrong' feels unfair to someone who was misled by a machine"
  },
  {
    "ce_mental_state_attribution": "the investigators seem clear on that",
    "ce_understood_harm": "Somebody died",
    "pd_harm_distress": "I picture that person and my stomach drops"
  }
